```c
stdlib_complex128_t stdlib_base_complex128_add3( const stdlib_complex128_t z1, const stdlib_complex128_t z2, const stdlib_complex128_t z3 ) {
	double re1;
	double im1;
	double re2;
	double im2;
	double re3;
	double im3;
	double re;
	double im;

	stdlib_complex128_reim( z1, &re1, &im1 );
	stdlib_complex128_reim( z2, &re2, &im2 );
	stdlib_complex128_reim( z3, &re3, &im3 );

	re = re1 + re2 + re3;
	im = im1 + im2 + im3;

	return stdlib_complex128( re, im );
}
```

#### add3 (lib/main.js:46)

```javascript
function add3( z1, z2, z3 ) {
	var re = real( z1 ) + real( z2 ) + real( z3 );
	var im = imag( z1 ) + imag( z2 ) + imag( z3 );
	return new Complex128( re, im );
}
```

#### add3 (lib/native.js:46)

```javascript
function add3( z1, z2, z3 ) {
	var v = addon( z1, z2, z3 );
	return new Complex128( v.re, v.im );
}
```

