static double benchmark( void ) {
	stdlib_complex128_t z1[ 100 ];
	stdlib_complex128_t z2[ 100 ];
	stdlib_complex128_t z3[ 100 ];
	stdlib_complex128_t z4;
	double elapsed;
	double re;
	double im;
	double t;
	int i;

	for ( i = 0; i < 100; i++ ) {
		re = ( 1000.0*rand_double() ) - 500.0;
		im = ( 1000.0*rand_double() ) - 500.0;
		z1[ i ] = stdlib_complex128( re, im );

		re = ( 1000.0*rand_double() ) - 500.0;
		im = ( 1000.0*rand_double() ) - 500.0;
		z2[ i ] = stdlib_complex128( re, im );

		re = ( 1000.0*rand_double() ) - 500.0;
		im = ( 1000.0*rand_double() ) - 500.0;
		z3[ i ] = stdlib_complex128( re, im );
	}

	t = tic();
	for ( i = 0; i < ITERATIONS; i++ ) {
		z4 = stdlib_base_complex128_add3( z1[ i%100 ], z2[ i%100 ], z3[ i%100 ] );
		stdlib_complex128_reim( z4, &re, &im );
		if ( re != re ) {
			printf( "should not return NaN\n" );
			break;
		}
	}
	elapsed = tic() - t;
	if ( im != im ) {
		printf( "should not return NaN\n" );
	}
	return elapsed;
}
```

